def apply(story:dict,i:int)->dict:
    # Tens and units yield a stable unique 10x10 combination for IDs 001..100.
    p=PERSONAL[(i-1)%10]
    c=COMMUNITY[((i-1)//10)%10]
    story['subplot']={
        'personalAr':p[0],'personalEn':p[1],'personalFr':p[2],
        'communityAr':c[0],'communityEn':c[1],'communityFr':c[2]
    }
    for j in range(10):
        ar=f'{p[0]}، {c[0]}. {EVOLUTION_AR[j]}'
        en=f'{p[1].capitalize()}, and {c[1]}. {EVOLUTION_EN[j]}'
        fr=f'{p[2].capitalize()}, tandis que {c[2]}. {EVOLUTION_FR[j]}'
        story['storyAr'][j]['text'] += ' '+ar
        story['storyEn'][j]['text'] += ' '+en
        story['storyFr'][j]['text'] += ' '+fr
        story['scenes'][j]['narration']=story['storyAr'][j]['text']
        story['scenes'][j]['narrationEn']=story['storyEn'][j]['text']
        story['scenes'][j]['narrationFr']=story['storyFr'][j]['text']
        story['scenes'][j]['subplotBeat']={'ar':EVOLUTION_AR[j],'en':EVOLUTION_EN[j],'fr':EVOLUTION_FR[j]}
    return story
